WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM sessions), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT CASE WHEN session_start_flag >= 1 THEN 'HIGH' ELSE 'LOW' END AS session_start_flag_tier, MIN(session_id) AS min_session_id, MAX(session_start_flag) FILTER (WHERE device = 'tablet') AS tablet_max_session_start_flag FROM sessionized GROUP BY CASE WHEN session_start_flag >= 1 THEN 'HIGH' ELSE 'LOW' END HAVING MAX(session_start_flag) FILTER (WHERE device = 'tablet') < 0 ORDER BY min_session_id
